// ── Run Config ──────────────────────────────────────────────────────
// Pricewire does the reading and applying on the site itself; this box only
// asks it to run (lib/price-watch/pricewire.ts). Nothing here chooses sites,
// brands or prices — the owner does that in Admin → Pricewire.
const appBaseUrl = ($env.PW_APP_URL || '').replace(/\/$/, '');
if (!appBaseUrl) throw new Error('PW_APP_URL is not set on the n8n container (e.g. https://www.kitchen-appliances.co.uk).');
return [{ json: { appBaseUrl, keyId: 'collector', deadlineMs: Number($env.PRICEWIRE_DEADLINE_MS || 230000) } }];

// ── Sign Pricewire Request ──────────────────────────────────────────
// HMAC per lib/machine-auth.ts: hex(HMAC_SHA256(secret, `${route}.${timestamp}.${rawBody}`)),
// route = 'pricewire'. The body is signed byte for byte, so it is built here and
// sent unchanged by the next node.
let crypto;
try { crypto = require('crypto'); } catch (e) {
  throw new Error('The Code node cannot require("crypto"). Set NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n container and restart it. See ops/n8n/README.md.');
}
const cfg = $input.first().json;
const envName = 'PRICE_INGEST_SECRET_' + String(cfg.keyId).toUpperCase().replace(/[^A-Z0-9]/g, '_');
const secret = $env[envName];
if (!secret) throw new Error('No secret in environment variable ' + envName + '.');
const timestamp = String(Math.floor(Date.now() / 1000));
const rawBody = JSON.stringify({ deadlineMs: cfg.deadlineMs });
const signature = crypto.createHmac('sha256', secret).update('pricewire.' + timestamp + '.' + rawBody, 'utf8').digest('hex');
return [{ json: { url: cfg.appBaseUrl + '/api/price-ingest/pricewire', rawBody, headers: { 'x-pw-key': cfg.keyId, 'x-pw-timestamp': timestamp, 'x-pw-signature': signature } } }];

// ── Run Summary ─────────────────────────────────────────────────────
const r = $input.first().json;
if (!r || r.ok !== true) throw new Error('Pricewire did not run: ' + JSON.stringify(r).slice(0, 300));
const read = r.read || {};
const brands = Object.entries(read.brands || {}).map(([b, t]) => `${b} ${t.priced}/${t.products} priced${t.unread ? `, ${t.unread} not readable` : ''}${t.left ? `, ${t.left} left` : ''}`).join('; ');
const sites = Object.entries(read.sites || {}).filter(([, t]) => t.error).map(([id, t]) => `${id}: ${t.error}`).join('; ');
return [{ json: { changed: r.changed, brands, applied: r.applied, siteProblems: sites || 'none' } }];
